//! Common schema field definitions for uniform `PluginSchema` structure across plugins.
//!
//! The canonical implementation lives in the `op-blob` crate
//! (`op_blob::sections`) — the single cohesive schema-pipeline crate — so the
//! same section shapes feed blob construction, UI, routing, compliance,
//! enforcement, memory, and audit trail. This file re-exports the public API
//! so all plugin files compile unchanged.
//!
//! See `op-blob/src/sections.rs` for the structs, the subid policy
//! (plugin-namespaced injection, global uniqueness), and the secrets policy.

pub use op_blob::sections::{
    inject_common_subids, AIModelConfig, NetworkInterface, PluginMetadata, SecurityKey,
    ServiceConfig,
};

