/// correctly. Root/field `x-oscal-subid` extensions populate `subids`;
/// `x-immutable-paths` populates `immutable_paths`.
pub fn plugin_schema_from_json(
    name: &str,
    version: &str,
    description: &str,
    root: &JVal,
