}

impl TypedQueryTool {
    fn new(
        name: &str,
        description: &str,
        namespace: &str,
        store: Arc<CognitiveMemoryStore>,
        sessions: Arc<SessionManager>,
        quota: Arc<QuotaManager>,
    ) -> Self {
