                    "score": point.score,
                    "payload": format!("{:?}", point.payload)
                })
            })
            .collect();

        Ok(json!({
            "count": count,
            "container_id": container_id,
            "results": items
        }))
    }

    async fn op_delete(&self, input: &Value) -> Result<Value> {
        let namespace = memory_namespace(input)?;
        let key = input["key"]
