pub fn get_global_dependencies() -> Vec<SystemDependency> {
    vec![
        SystemDependency::required("openvswitch-switch"),
        SystemDependency::optional("btrfs-progs"),
        SystemDependency::optional("numactl"),
        SystemDependency::optional("jq"),
    ]
}

