    /// Declared signals emitted by the plugin.
    #[serde(default)]
    pub signals: Vec<SignalDecl>,
    /// Plugin capability guarantees (4-field canonical block).
    #[serde(default)]
    pub guarantees: PluginCapabilities,
}

